CREATE TABLE IF NOT EXISTS surahs (id INTEGER PRIMARY KEY, number INTEGER UNIQUE NOT NULL, name TEXT NOT NULL, arabic_name TEXT NOT NULL, transliteration TEXT NOT NULL, slug TEXT UNIQUE NOT NULL, revelation_type TEXT NOT NULL CHECK(revelation_type IN ('Makki','Madani')), ayah_count INTEGER NOT NULL, sort_order INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS reciters (id TEXT PRIMARY KEY, name TEXT NOT NULL, slug TEXT UNIQUE NOT NULL, description TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS audio_files (id TEXT PRIMARY KEY, storage_key TEXT UNIQUE NOT NULL, original_name TEXT NOT NULL, content_type TEXT NOT NULL, size INTEGER NOT NULL, duration REAL NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS recordings (id TEXT PRIMARY KEY, surah_id INTEGER NOT NULL REFERENCES surahs(id), reciter_id TEXT NOT NULL REFERENCES reciters(id), audio_id TEXT NOT NULL REFERENCES audio_files(id), title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', status TEXT NOT NULL CHECK(status IN ('draft','published','unpublished')), featured INTEGER NOT NULL DEFAULT 0, allow_download INTEGER NOT NULL DEFAULT 0, rights_confirmed INTEGER NOT NULL DEFAULT 0, sort_order INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS ayah_timestamps (recording_id TEXT NOT NULL REFERENCES recordings(id) ON DELETE CASCADE, ayah_number INTEGER NOT NULL, start_seconds REAL NOT NULL, PRIMARY KEY(recording_id,ayah_number));
CREATE TABLE IF NOT EXISTS admin_sessions (token_hash TEXT PRIMARY KEY, expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS login_attempts (key TEXT PRIMARY KEY, count INTEGER NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS recordings_public ON recordings(status,sort_order,surah_id);
